interface.signature:
class EventManager {
  private activeEvents: GameEvent[];
  spawnEvent(level: number): GameEvent | null;
  getActiveEvents(): GameEvent[];
  getMaxSimultaneousEvents(level: number): number;
}

interface GameEvent {
  id: string;
  type: EventType;
  priority: EventPriority;
  location: { x: number; y: number };
  timer: number;
  points: number;
  cozinessReward: number;
  cozinessPenalty: number;
}
